---@alias gcp.dfareporting_v5.DayPartTargetingDaysOfWeekItemEnum "SUNDAY"|"MONDAY"|"TUESDAY"|"WEDNESDAY"|"THURSDAY"|"FRIDAY"|"SATURDAY"

